validator:
function validate(input) {
  const [{ Candidates = [] }] = input;
  const ids = new Set();
  for (const [id, experience, salary] of Candidates) {
    if (id === null) return 'Every candidate needs an employee_id.';
    if (ids.has(id)) return `employee_id ${id} appears twice in Candidates.`;
    ids.add(id);
    if (experience !== 'Senior' && experience !== 'Junior') return `experience must be 'Senior' or 'Junior', not ${experience}.`;
    if (salary === null || salary <= 0) return `Candidate ${id} needs a positive salary.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const Candidates = [];
  if (size === 'small') {
    // A few salaries that add up to the budget exactly, tie with each other, or exceed it alone.
    const salaries = [5000, 10000, 15000, 20000, 25000, 30000, 35000, 40000, 50000, 70000, 80000];
    const ids = Array.from({ length: 15 }, (_, i) => i + 1);
    for (let i = ids.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [ids[i], ids[j]] = [ids[j], ids[i]]; }
    const count = Math.floor(rand() * 9);
    const seniorShare = rand();
    for (let i = 0; i < count; i++) Candidates.push([ids[i], rand() < seniorShare ? 'Senior' : 'Junior', pick(salaries)]);
    return [{ Candidates }];
  }
  // Large: salaries spread so that only the cheapest few dozen fit in the budget.
  const span = { Senior: pick([40000, 150000, 600000]), Junior: pick([20000, 80000, 300000]) };
  for (let id = 1; id <= 2000; id++) {
    const experience = rand() < 0.5 ? 'Senior' : 'Junior';
    Candidates.push([id, experience, 100 * (1 + Math.floor(rand() * span[experience] / 100))]);
  }
  return [{ Candidates }];
}
